// 解析 Bitbucket Server API 返回的 PR 数据
const response = $input.item.json;
const prs = response.values || [];

// 获取配置信息
const config = {
  BITBUCKET_API_URL: $('⚙️ 配置中心 (自建版配置)').item.json.BITBUCKET_API_URL,
  BITBUCKET_PROJECT: $('⚙️ 配置中心 (自建版配置)').item.json.BITBUCKET_PROJECT,
  BITBUCKET_REPO: $('⚙️ 配置中心 (自建版配置)').item.json.BITBUCKET_REPO,
  BITBUCKET_API_VERSION: $('⚙️ 配置中心 (自建版配置)').item.json.BITBUCKET_API_VERSION,
  FEISHU_APP_TOKEN: $('⚙️ 配置中心 (自建版配置)').item.json.FEISHU_APP_TOKEN,
  FEISHU_TABLE_ID: $('⚙️ 配置中心 (自建版配置)').item.json.FEISHU_TABLE_ID
};

if (prs.length === 0) {
  return [];
}

// 过滤今天创建的 PR
const today = new Date();
today.setHours(0, 0, 0, 0);
const todayTimestamp = today.getTime();

const todayPRs = prs.filter(pr => {
  const createdDate = new Date(pr.createdDate);
  return createdDate.getTime() >= todayTimestamp;
});

if (todayPRs.length === 0) {
  return [];
}

// 为每个 PR 创建输出项
return todayPRs.map(pr => {
  // Bitbucket Server 的链接格式
  const prLink = `${config.BITBUCKET_API_URL}/projects/${config.BITBUCKET_PROJECT}/repos/${config.BITBUCKET_REPO}/pull-requests/${pr.id}`;

  // 构造 diff URL（Bitbucket Server REST API）
  const diffUrl = `${config.BITBUCKET_API_URL}/rest/api/${config.BITBUCKET_API_VERSION}/projects/${config.BITBUCKET_PROJECT}/repos/${config.BITBUCKET_REPO}/pull-requests/${pr.id}/diff`;

  return {
    json: {
      pr_id: pr.id,
      pr_title: pr.title || '',
      pr_description: pr.description || '',
      pr_author: pr.author?.user?.displayName || pr.author?.user?.name || 'Unknown',
      pr_author_email: pr.author?.user?.emailAddress || '',
      pr_source_branch: pr.fromRef?.displayId || pr.fromRef?.id || '',
      pr_destination_branch: pr.toRef?.displayId || pr.toRef?.id || '',
      pr_created_date: new Date(pr.createdDate).toISOString(),
      pr_updated_date: new Date(pr.updatedDate).toISOString(),
      pr_link: prLink,
      diff_url: diffUrl,
      _config: config
    }
  };
});

// 准备发送给千问的 prompt
const prData = $input.item.json;
const diffContent = prData.data || '';

// 限制 diff 内容长度，避免 token 过多
const maxDiffLength = 8000;
const truncatedDiff = diffContent.length > maxDiffLength 
  ? diffContent.substring(0, maxDiffLength) + '\n... (内容已截断)'
  : diffContent;

const prompt = `你是一个资深的代码审查专家。请对以下 Pull Request 进行全面评估：

**PR 信息：**
- 标题：${prData.pr_title}
- 描述：${prData.pr_description}
- 作者：${prData.pr_author}
- 源分支：${prData.pr_source_branch}
- 目标分支：${prData.pr_destination_branch}

**代码变更（Diff）：**
\`\`\`diff
${truncatedDiff}
\`\`\`

请从以下维度进行评估：
1. **代码缺陷**：是否存在逻辑错误、边界条件问题、空指针等
2. **注释程度**：代码注释是否充分、清晰
3. **合理性**：代码设计是否合理、是否遵循最佳实践
4. **安全性**：是否存在安全漏洞、敏感信息泄露等

请按照以下 JSON 格式返回评估结果：
{
  "issues": [
    {
      "level": "高|中|低",
      "category": "代码缺陷|注释程度|合理性|安全性",
      "description": "问题描述",
      "location": "代码位置或文件名",
      "suggestion": "改进建议"
    }
  ],
  "overall_score": "0-100 分",
  "summary": "总体评价"
}`;

return [{
  json: {
    ...prData,
    diff_content: truncatedDiff,
    ai_prompt: prompt
  }
}];

